 Agra. Home to the wonderful Taj Mahal, Agra catches attention of visitors with its rich Mughal tradition. Explore grand forts, beautiful gardens, and everlasting architectural wonders.\nUpon checking into your hotel and relaxing for a bit, we will start our exploration of Agra''s highlights:\nOvernight stay at a hotel in Agra.", "start_time": "09:00", "end_time": "18:00", "travel_distance_km": null, "travel_time_minutes": null, "location": "Delhi", "hotel_name": null, "room_category": null, "meal_plan": "CP", "breakfast": true, "lunch": false, "dinner": true, "breakfast_hotels": [null, null], "lunch_hotels": [null, null], "dinner_hotels": [null, null], "epai_plan_only": false, "guest_self_booked_hotel": false, "vehicle_type": "AC Car", "pickup_location": null, "drop_location": null, "guide_required": true, "activities": [{"activity_uuid": "71ed5db3-d7a5-f10d-3a3e-fc7fe123ff0c", "sort_order": 0, "title": "Taj Mahal", "description": "Discover the eternal symbol of love.", "start_time": null, "end_time": null, "entry_fee": 0, "guide_required": false}, {"activity_uuid": "c44b5640-4f75-84da-8e15-a8bf55217e12", "sort_order": 1, "title": "Agra Fort", "description": "Explore the grandeur of Mughal architecture.", "start_time": null, "end_time": null, "entry_fee": 0, "guide_required": false}, {"activity_uuid": "fc6cf48c-927e-559d-86cd-920746557263", "sort_order": 2, "title": "Itimad-Ud-Daulah", "description": "Admire exquisite marble craftsmanship.", "start_time": null, "end_time": null, "entry_fee": 0, "guide_required": false}, {"activity_uuid": "e7020e86-6dbb-392f-c640-a411dc1d161b", "sort_order": 3, "title": "Local markets and bazaars", "description": "Delve into Agra''s vibrant shopping scene.", "start_time": null, "end_time": null, "entry_fee": 0, "guide_required": false}], "images": [], "internal_notes": "", "client_notes": "", "operations_notes": "", "status": "planned", "completion_pct": 0, "packing_tips": "", "things_to_carry": []}, {"day_uuid": "0ea7d4ce-349e-356c